        m.put("type", type);
        m.put("cursor", cursor);
        m.put("resume", resume);
        m.put("data", data);
        return write(m);
    }

    /** 慢消费者丢帧通知；fromCursor/toCursor 为被丢弃的最旧到最新未确认游标闭区间。 */
    public static String resumeGap(String topic, long fromCursor, long toCursor) {
