/**
 * 共享订阅消息账本：保存每个共享订阅最近 N 条 (cursor, data)，
 * 用于同一 JVM 内断线重连且 ACK 之后的补发。线程安全。
 */
public interface MessageLedger {

    /** 追加一条已分配游标的消息。 */
    void append(SubscriptionKey key, long cursor, String type, JsonNode data);

    /** 取出游标严格大于 afterCursor 的可用消息（按游标升序）。 */
    List<LedgerEntry> after(SubscriptionKey key, long afterCursor);

    record LedgerEntry(long cursor, String type, JsonNode data) {
    }
}

package com.example.starter.rosbridge.gateway;

/**
 * 单客户端发送会话：维护有界发送队列、令牌桶速率限制与 WebSocket 写出。
 * 队列满时丢弃该客户端最旧未确认消息并生成 RESUME_GAP，不影响其他客户端。
 */
public interface ClientSession {

    /** 入队一条待发送帧；慢消费者满队列时按协议丢弃旧帧。 */
    void enqueue(OutboundFrame frame);

    /** 关闭会话并释放资源。 */
    void close();

    boolean isOpen();
}

package com.example.starter.rosbridge.gateway;

/**
 * 待发往客户端的一帧。topic 帧携带游标用于慢消费者丢弃与 ACK 跟踪。
 */
public record OutboundFrame(String payload, String topic, long cursor, boolean topicFrame) {

    public static OutboundFrame control(String payload) {
        return new OutboundFrame(payload, null, 0, false);
    }

    public static OutboundFrame topic(String payload, String topic, long cursor) {
        return new OutboundFrame(payload, topic, cursor, true);
    }
}

