package com.example.starter.rosbridge.gateway;

import com.example.starter.rosbridge.protocol.Frames;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.socket.WebSocketSession;

/**
 * 单客户端发送会话：
 * <ul>
 *   <li>有界发送队列（容量可按客户端配置）；</li>
 *   <li>令牌桶发送速率限制；</li>
 *   <li>队列满时只丢弃该客户端最旧的未确认 Topic 帧，聚合成
 *       {@code RESUME_GAP}（含丢失游标闭区间）插到新消息之前，不影响其他客户端。</li>
 * </ul>
 */
public class WebSocketClientSession implements ClientSession {

    private static final Logger log = LoggerFactory.getLogger(WebSocketClientSession.class);

    private final String clientId;
    private final FrameSink sink;
    private final int capacity;
    private final double ratePerSecond;

    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notEmpty = lock.newCondition();
    private final LinkedList<OutboundFrame> queue = new LinkedList<>();
    private final Thread senderThread;
    private volatile boolean open = true;

    /** topic -> 客户端已 ACK 游标。 */
    private final Map<String, Long> ackedCursors = new ConcurrentHashMap<>();
    /** topic -> 待通知的丢帧区间。 */
    private Long gapFrom;
    private Long gapTo;
    private String gapTopic;

    // 令牌桶
    private double tokens;
    private long lastRefillNanos = System.nanoTime();

    public WebSocketClientSession(String clientId, WebSocketSession session, int capacity, int ratePerSecond) {
        this(clientId, payload -> {
            synchronized (session) {
                if (session.isOpen()) {
                    session.sendMessage(new org.springframework.web.socket.TextMessage(payload));
                }
            }
        }, capacity, ratePerSecond);
    }

    public WebSocketClientSession(String clientId, FrameSink sink, int capacity, int ratePerSecond) {
        this.clientId = clientId;
        this.sink = sink;
        this.capacity = Math.max(2, capacity);
        this.ratePerSecond = ratePerSecond;
        this.tokens = Math.max(1.0, ratePerSecond);
        this.senderThread = new Thread(this::sendLoop, "ws-sender-" + clientId);
        this.senderThread.setDaemon(true);
        this.senderThread.start();
    }

    /** 更新该客户端某 Topic 的已确认游标（仅前进）。 */
    public void acknowledge(String topic, long cursor) {
        ackedCursors.merge(topic, cursor, Math::max);
    }

    @Override
    public void enqueue(OutboundFrame frame) {
        lock.lock();
        try {
            if (!open) {
                return;
            }
            if (frame.topicFrame()) {
                while (queue.size() >= capacity) {
                    evictOldestUnacked();
                }
                queue.addLast(frame);
                flushGapLocked();
            } else {
                // 控制帧不丢弃；极端情况下仍满则继续淘汰最旧未确认 Topic 帧
                while (queue.size() >= capacity) {
                    evictOldestUnacked();
                }
                queue.addLast(frame);
            }
            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }

    /**
     * 丢弃队列中最旧的未确认 Topic 帧并累积丢失区间；
     * 连续游标合并为一个区间，非连续则先冲刷上一个 RESUME_GAP。
     */
    private void evictOldestUnacked() {
        Iterator<OutboundFrame> it = queue.iterator();
        while (it.hasNext()) {
            OutboundFrame f = it.next();
            if (!f.topicFrame()) {
                continue;
            }
            long acked = ackedCursors.getOrDefault(f.topic(), 0L);
            if (f.cursor() <= acked) {
                // 已被确认（理论上罕见），直接移除且不通知
                it.remove();
                return;
            }
            it.remove();
            long c = f.cursor();
            if (gapTopic == null || !gapTopic.equals(f.topic())) {
                flushGapLocked();
                gapTopic = f.topic();
                gapFrom = c;
                gapTo = c;
            } else if (gapTo != null && c == gapTo + 1) {
                gapTo = c;
            } else {
                flushGapLocked();
                gapFrom = c;
                gapTo = c;
            }
            log.debug("client={} slow consumer, dropped cursor={} topic={}", clientId, c, f.topic());
            return;
        }
        // 没有可丢弃的 Topic 帧（队列里全是控制帧），移除最旧帧保证有界
        if (!queue.isEmpty()) {
            queue.removeFirst();
        }
    }

    /** 将累积的丢帧区间作为 RESUME_GAP 插到队列最前，确保先于后续数据送达。 */
    private void flushGapLocked() {
        if (gapTopic == null) {
            return;
        }
        queue.addFirst(OutboundFrame.control(Frames.resumeGap(gapTopic, gapFrom, gapTo)));
        gapTopic = null;
        gapFrom = null;
        gapTo = null;
    }

    private void sendLoop() {
        while (true) {
            OutboundFrame frame;
            lock.lock();
            try {
                while (queue.isEmpty() && open) {
                    notEmpty.awaitUninterruptibly();
                }
                if (queue.isEmpty()) {
                    flushGapLocked();
                    return;
                }
                frame = queue.removeFirst();
            } finally {
                lock.unlock();
            }
            acquireRatePermit();
            try {
                sink.send(frame.payload());
            } catch (Exception e) {
                log.warn("client={} send failed, closing session: {}", clientId, e.toString());
                close();
                return;
            }
        }
    }

    private void acquireRatePermit() {
        if (ratePerSecond <= 0) {
            return;
        }
        long waitNanos;
        lock.lock();
        try {
            refill();
            if (tokens < 1.0) {
                waitNanos = (long) ((1.0 - tokens) * 1_000_000_000L / ratePerSecond);
            } else {
                waitNanos = 0;
            }
            if (waitNanos > 0) {
                // 锁外等待后在下方重新结算令牌
            }
        } finally {
            lock.unlock();
        }
        if (waitNanos > 0) {
            try {
                Thread.sleep(waitNanos / 1_000_000L, (int) (waitNanos % 1_000_000L));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        lock.lock();
        try {
            refill();
            tokens -= 1.0;
        } finally {
            lock.unlock();
        }
    }

    private void refill() {
        long now = System.nanoTime();
        double elapsedSeconds = (now - lastRefillNanos) / 1_000_000_000.0;
        if (elapsedSeconds > 0) {
            tokens = Math.min(Math.max(1.0, ratePerSecond), tokens + elapsedSeconds * ratePerSecond);
            lastRefillNanos = now;
        }
    }

    /** 测试辅助：等待队列中的帧全部发送完成。 */
    public void awaitDrained(long timeoutMillis) throws InterruptedException {
        long deadline = System.currentTimeMillis() + timeoutMillis;
        while (System.currentTimeMillis() < deadline) {
            lock.lock();
            try {
                if (queue.isEmpty()) {
                    return;
                }
            } finally {
                lock.unlock();
            }
            Thread.sleep(5);
        }
    }

    /** 测试辅助：当前排队帧数。 */
    public int queuedSize() {
        lock.lock();
        try {
            return queue.size();
        } finally {
            lock.unlock();
        }
    }

    @Override
    public void close() {
        lock.lock();
        try {
            if (!open) {
                return;
            }
            open = false;
            notEmpty.signalAll();
        } finally {
            lock.unlock();
        }
    }

    @Override
    public boolean isOpen() {
        return open;
    }
}

