        assertThat(resp).isNotNull();
        assertThat(resp.path("status").asText()).isEqualTo("TIMEOUT");
        assertThat(repository.getCallStatus("svc", "r1")).isEqualTo("TIMEOUT");
        // 不应有第二个响应（重复请求幂等 + 迟到结果不再完成）
        List<JsonNode> rest = sessions.drain("svc");
