        assertThat(gap).isNotNull();
        assertThat(gap.path("fromCursor").asLong()).isEqualTo(2);
        assertThat(gap.path("toCursor").asLong()).isEqualTo(2);
        List<Long> topicCursors = topicCursors(sent);
        assertThat(topicCursors).containsExactly(1L, 3L, 4L, 5L, 6L);
        // GAP 必须排在被丢帧之后的数据之前
        assertThat(sent.indexOf(gapPayload(gap))).isLessThan(sent.indexOf(topicPayload(3)));
    }

    @Test
    void consecutiveDropsMergeIntoSingleGapRange() throws Exception {
        List<String> sent = new ArrayList<>();
        CountDownLatch mayProceed = new CountDownLatch(1);
