private void scheduleGraceRelease(SubscriptionKey key) {
    SharedSubscription shared = sharedSubscriptions.get(key);
    if (shared == null) {
        return;
    }
    long delay = Math.max(0, properties.gracePeriodMs());
    shared.graceTask = scheduler.schedule(() -> releaseUpstreamIfUnreferenced(key), delay, TimeUnit.MILLISECONDS);
}

/** 宽限结束：仅当引用计数仍为 0（期间无重新订阅）才真正释放上游资源。 */
private void releaseUpstreamIfUnreferenced(SubscriptionKey key) {
    if (repository.getRefcount(key) > 0) {
        return;
    }
    SharedSubscription shared = sharedSubscriptions.remove(key);
    if (shared == null) {
        return;
    }
    try {
        shared.rosSubscription.close();
    } catch (Exception e) {
        log.warn("close upstream subscription failed: {}", e.toString());
    }
    repository.deleteRefIfZero(key);
    ledger.remove(key);
    log.info("upstream subscription released after grace: {}", key);
}

